#include <bits/stdc++.h>
using namespace std;
int main() {
    string a, b;
    cin >> a >> b;
    string c;
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        c.push_back(s % 10 + '0');
        carry = s / 10;
    }
    reverse(c.begin(), c.end());
    cout << c << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    long long v1, v2, t, s, l;
    cin >> v1 >> v2 >> t >> s >> l;
    long long r = 0, w = 0, rest = 0, sec = 0;
    while (r < l && w < l) {
        sec++;
        if (rest > 0) rest--;
        else {
            r += v1;
            if (r - w >= t && r < l) rest = s;
        }
        w += v2;
    }
    if (r >= l && w >= l) cout << "D\n";
    else if (w >= l) cout << "T\n";
    else cout << "R\n";
    cout << sec << endl;
    return 0;
}
